import sys, gc, weakref
sys.path.insert(0, '/tmp')
import py311_shim
from tornado import gen
from tornado.testing import AsyncHTTPTestCase, gen_test
from tornado.web import Application
from tornado.websocket import WebSocketHandler, websocket_connect
import unittest

handler_ref = [None]

class H(WebSocketHandler):
    def on_message(self, m):
        self.write_message(m)

class T(AsyncHTTPTestCase):
    def get_app(self):
        return Application([('/ws', H)])
    @gen_test
    def test_gc(self):
        ws = yield websocket_connect('ws://private-network:%d/ws' % self.get_http_port())
        ws.write_message('hi')
        yield ws.read_message()
        for obj in gc.get_objects():
            if isinstance(obj, H):
                handler_ref[0] = weakref.ref(obj)
        ws.close()
        yield gen.sleep(0.05)
        self.assertIsNone(handler_ref[0](), 'handler still alive after close (no gc)')

r = unittest.TextTestRunner().run(unittest.TestLoader().loadTestsFromTestCase(T))
sys.exit(0 if r.wasSuccessful() else 1)
